// ⚠️ RATE LIMITER: 10 emails per day per email address
const items = $input.all();

// Get current date (YYYY-MM-DD)
const today = new Date().toISOString().split('T')[0];

// Access n8n's static data storage (persists between executions)
const staticData = $getWorkflowStaticData('global');

// Initialize rate limit storage if not exists
if (!staticData.rateLimits) {
  staticData.rateLimits = {};
}

// Clean up old dates (older than today)
Object.keys(staticData.rateLimits).forEach(key => {
  if (!key.includes(today)) {
    delete staticData.rateLimits[key];
  }
});

// Process each item
const processedItems = [];

for (const item of items) {
  const email = item.json.recipient || item.json.recipient_email;

  if (!email) {
    throw new Error('No recipient email found in data');
  }

  // Create unique key: email_YYYY-MM-DD
  const rateLimitKey = `${email}_${today}`;

  // Get current count for this email today
  if (!staticData.rateLimits[rateLimitKey]) {
    staticData.rateLimits[rateLimitKey] = 0;
  }

  // Increment counter
  staticData.rateLimits[rateLimitKey]++;

  const currentCount = staticData.rateLimits[rateLimitKey];

  // Check if limit exceeded
  if (currentCount > 10) {
    console.error(`❌ Rate limit exceeded for ${email}: ${currentCount} emails today`);
    throw new Error(
      `Rate limit exceeded: ${email} has already received ${currentCount - 1} emails today. ` +
      `Daily limit is 10 emails per recipient. Please try again tomorrow.`
    );
  }

  // Log successful rate check
  console.log(`✅ Rate check passed for ${email}: ${currentCount}/10 emails today`);

  // Add rate limit info to the item
  item.json.rate_limit_info = {
    email: email,
    count_today: currentCount,
    limit: 10,
    remaining: 10 - currentCount,
    date: today
  };

  processedItems.push(item);
}

return processedItems;

// Generic Certificate Email Processor
// Works for any organization - fully customizable

const items = $input.all();

// Debug: Log incoming data
console.log('Received items:', JSON.stringify(items, null, 2));

// Validate incoming data
if (!items || items.length === 0) {
  throw new Error('No input data received from webhook');
}

// Process each certificate email
for (const item of items) {
  console.log('Processing item:', JSON.stringify(item.json, null, 2));

  // Extract data from webhook - handle nested 'body' property
  let data = item.json;

  if (data.body) {
    if (typeof data.body === 'string') {
      try {
        data = JSON.parse(data.body);
      } catch (e) {
        console.log('Could not parse body string, using original data');
      }
    } else if (typeof data.body === 'object') {
      data = data.body;
    }
  }

  // Extract fields with customizable defaults
  const {
    recipient_email,
    recipient_name,
    certificate_image,  // Base64 image data
    subject = 'Your Certificate of Achievement',
    message = 'Congratulations on your achievement!',

    // Customizable email branding (all optional)
    email_header_title = '🎓 Certificate of Achievement',
    email_header_subtitle = 'Professional Certification Program',
    email_footer_company = 'Your Organization',
    email_footer_dept = 'Certification Department',
    email_sender_name = 'Certification Team',

    // Customizable colors (HSLA format for flexibility)
    primary_color = 'hsla(220, 90%, 56%, 1)',      // Default: Blue
    secondary_color = 'hsla(220, 90%, 35%, 1)',    // Default: Dark Blue
    accent_color = 'hsla(45, 100%, 51%, 1)',       // Default: Gold
    highlight_color = 'hsla(10, 90%, 50%, 1)'      // Default: Red
  } = data;

  // Debug extracted values
  console.log('Email:', recipient_email);
  console.log('Name:', recipient_name);
  console.log('Image size:', certificate_image ? certificate_image.length : 'undefined');

  // Validate required fields
  if (!recipient_email) {
    throw new Error(`recipient_email is required. Received: ${JSON.stringify(data)}`);
  }
  if (!recipient_name) {
    throw new Error(`recipient_name is required. Received: ${JSON.stringify(data)}`);
  }
  if (!certificate_image) {
    throw new Error(`certificate_image is required. Received: ${JSON.stringify(data)}`);
  }

  // Process certificate image
  let base64Data = certificate_image;

  // Remove data URL prefix if exists
  if (base64Data && base64Data.startsWith('data:')) {
    base64Data = base64Data.split(',')[1];
  }

  // Validate base64 data
  if (!base64Data || base64Data.trim().length === 0) {
    throw new Error('certificate_image is empty or invalid');
  }

  // Convert to Buffer for email attachment
  let buffer;
  try {
    buffer = Buffer.from(base64Data, 'base64');
  } catch (error) {
    throw new Error(`Failed to convert base64: ${error.message}`);
  }

  if (buffer.length === 0) {
    throw new Error('Generated buffer is empty - invalid base64 data');
  }

  console.log('Buffer created, size:', buffer.length);

  // Prepare attachment
  item.binary = {
    certificate: {
      data: buffer.toString('base64'),
      mimeType: 'image/png',
      fileName: `Certificate_${recipient_name.replace(/\s+/g, '_')}.png`
    }
  };

  // Build customizable HTML email
  const htmlEmail = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }
    body { 
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
      line-height: 1.6;
      color: #2c3e50;
      background-color: #f4f6f9;
    }
    .email-container {
      width: 100%;
      background-color: #f4f6f9;
      padding: 0;
      margin: 0;
    }
    .email-content {
      max-width: 100%;
      margin: 0 auto;
      background-color: #ffffff;
    }
    .header {
      background: linear-gradient(135deg, ${primary_color} 0%, ${secondary_color} 100%);
      padding: 50px 40px;
      text-align: center;
      color: #ffffff;
    }
    .header-title {
      font-size: 32px;
      font-weight: 700;
      margin: 0 0 10px 0;
      letter-spacing: 0.5px;
      text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
    }
    .header-subtitle {
      font-size: 16px;
      font-weight: 400;
      opacity: 0.95;
      margin: 0;
    }
    .content-wrapper {
      padding: 50px 60px;
      background-color: #ffffff;
    }
    .message-body {
      font-size: 16px;
      color: #34495e;
      line-height: 1.9;
      white-space: pre-line;
      margin: 0;
      padding: 25px;
      background-color: #f8f9fa;
      border-left: 4px solid ${primary_color};
      border-radius: 4px;
    }
    .footer {
      background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
      color: #ffffff;
      padding: 40px 60px;
      text-align: center;
    }
    .footer-company {
      font-size: 24px;
      font-weight: 700;
      margin-bottom: 15px;
      color: ${accent_color};
      text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.5);
    }
    .footer-divider {
      height: 2px;
      background: ${accent_color};
      margin: 20px auto;
      max-width: 200px;
      opacity: 0.8;
    }
    .footer-text {
      font-size: 14px;
      color: rgba(255, 255, 255, 0.85);
      margin: 8px 0;
      line-height: 1.6;
    }
    .footer-disclaimer {
      font-size: 11px;
      color: rgba(255, 255, 255, 0.6);
      margin-top: 25px;
      padding-top: 20px;
      border-top: 1px solid rgba(255, 255, 255, 0.1);
      font-style: italic;
    }
    @media only screen and (max-width: 600px) {
      .content-wrapper, .footer, .header {
        padding: 30px 20px !important;
      }
      .header-title {
        font-size: 24px !important;
      }
    }
  </style>
</head>
<body>
  <div class="email-container">
    <table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f4f6f9;">
      <tr>
        <td>
          <div class="email-content">

            <div class="header">
              <h1 class="header-title">${email_header_title}</h1>
              <p class="header-subtitle">${email_header_subtitle}</p>
            </div>

            <div class="content-wrapper">
              <div class="message-body">${message}</div>
            </div>

            <div class="footer">
              <div class="footer-company">${email_footer_company}</div>
              <div class="footer-divider"></div>
              <p class="footer-text">${email_footer_dept}</p>
              <p class="footer-text">This is an automated message from our certificate delivery system.</p>
              <p class="footer-disclaimer">
                This message contains confidential information and is intended only for the individual named.
                <br><br>
                © ${new Date().getFullYear()} ${email_footer_company}. All rights reserved.
              </p>
            </div>

          </div>
        </td>
      </tr>
    </table>
  </div>
</body>
</html>
  `;

  // Store data for Gmail node
  item.json.recipient = recipient_email;
  item.json.subject = subject;
  item.json.html_message = htmlEmail;
  item.json.recipient_name = recipient_name;

  console.log('✅ Successfully processed for:', recipient_email);
}

return items;
